#!/usr/bin/env python3\n\"\"\"Validator for Ethereum‑like addresses (EIP‑55 checksum). Accepts chain and address via CLI or stdin. Outputs JSON result.\"\"\"\nimport sys, json, re, hashlib\n\ndef is_valid_eth_address(addr):\n    if not isinstance(addr, str):\n        return False\n    if not re.fullmatch(r'0x[0-9a-fA-F]{40}', addr):\n        return False\n    # checksum verification (EIP‑55)\n    addr_body = addr[2:]\n    addr_lower = addr_body.lower()\n    keccak = hashlib.sha3_256()\n    keccak.update(addr_lower.encode())\n    hash_hex = keccak.hexdigest()\n    for i, c in enumerate(addr_body):\n        if c.isalpha():\n            if int(hash_hex[i], 16) >= 8:\n                if c != c.upper():\n                    return False\n            else:\n                if c != c.lower():\n                    return False\n    return True\n\ndef main():\n    if len(sys.argv) >= 3:\n        chain = sys.argv[1].lower()\n        address = sys.argv[2]\n    else:\n        data = sys.stdin.read().strip().split()\n        if len(data) >= 2:\n            chain, address = data[0].lower(), data[1]\n        else:\n            print(json.dumps({\"error\": \"Missing arguments\"}))\n            sys.exit(1)\n    result = {\n        \"chain\": chain,\n        \"address\": address,\n        \"valid\": is_valid_eth_address(address)\n    }\n    print(json.dumps(result))\n\nif __name__ == \"__main__\":\n    main()\n